async function body(req){let t='';for await(const b of req){t+=b;if(t.length>maxBody)throw Error('Request too large')}try{return JSON.parse(t||'{}')}catch{throw Error('Invalid JSON')}}
async function dbAll(table,queryString=''){const params=new URLSearchParams(queryString);params.delete('limit');params.delete('offset');let offset=0,all=[];while(true){const q=new URLSearchParams(params);q.set('limit','1000');q.set('offset',String(offset));const batch=await db(table,{query:q.toString()});all.push(...batch);if(batch.length<1000)break;offset+=batch.length;}return all;}
async function auth(req,role='editor'){const token=req.headers.authorization?.match(/^Bearer (.+)$/i)?.[1];const u=await currentUser(token);return u&&(role==='editor'||u.role==='admin')?u:null}
async function supabaseAuthUser(token){
 if(!token||!process.env.SUPABASE_URL)return null;
 const base=process.env.SUPABASE_URL.replace(/\/$/,'');
 const key=process.env.SUPABASE_ANON_KEY||process.env.SUPABASE_SERVICE_ROLE_KEY;
 const r=await fetch(`${base}/auth/v1/user`,{headers:{apikey:key,Authorization:`Bearer ${token}`}});
 if(!r.ok)return null;const user=await r.json();return user?.id?user:null;
}
async function employerAuth(req){
 const token=req.headers.authorization?.match(/^Bearer (.+)$/i)?.[1];const user=await supabaseAuthUser(token);if(!user)return null;
 const rows=await db('employers',{query:`select=*&id=eq.${encodeURIComponent(user.id)}&limit=1`});
 return rows[0]?.status==='active'?rows[0]:null;
}
async function rawBody(req,limit=8500000){const chunks=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>limit)throw Error('Request too large');chunks.push(chunk);}return Buffer.concat(chunks);}
async function uploadPrivateObject(objectPath,bytes,mime){
 const base=process.env.SUPABASE_URL?.replace(/\/$/,'');const key=process.env.SUPABASE_SERVICE_ROLE_KEY;if(!base||!key)throw Error('Supabase storage is not configured.');
 const encoded=objectPath.split('/').map(encodeURIComponent).join('/');const r=await fetch(`${base}/storage/v1/object/findjob-private/${encoded}`,{method:'POST',headers:{Authorization:`Bearer ${key}`,apikey:key,'Content-Type':mime,'x-upsert':'false'},body:bytes});
 if(!r.ok){const detail=(await r.text()).slice(0,220);throw Error(`CV upload failed (${r.status}). ${detail||'Check the private findjob-private storage bucket.'}`);}return objectPath;
}
async function signedPrivateUrl(objectPath,filename){const base=process.env.SUPABASE_URL?.replace(/\/$/,'');const key=process.env.SUPABASE_SERVICE_ROLE_KEY;const encoded=objectPath.split('/').map(encodeURIComponent).join('/');const r=await fetch(`${base}/storage/v1/object/sign/findjob-private/${encoded}`,{method:'POST',headers:{Authorization:`Bearer ${key}`,apikey:key,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:300,download:filename||true})});const data=await r.json().catch(()=>({}));if(!r.ok||!data.signedURL)throw Error('Could not create a secure CV download link.');return data.signedURL.startsWith('http')?data.signedURL:`${base}/storage/v1${data.signedURL}`;}
async function downloadPrivateObject(objectPath){const base=process.env.SUPABASE_URL?.replace(/\/$/,'');const key=process.env.SUPABASE_SERVICE_ROLE_KEY;const encoded=objectPath.split('/').map(encodeURIComponent).join('/');const r=await fetch(`${base}/storage/v1/object/authenticated/findjob-private/${encoded}`,{headers:{Authorization:`Bearer ${key}`,apikey:key}});if(!r.ok)throw Error('A CV file could not be downloaded from private storage.');return Buffer.from(await r.arrayBuffer());}
async function removePrivateObject(objectPath){try{const base=process.env.SUPABASE_URL?.replace(/\/$/,'');const key=process.env.SUPABASE_SERVICE_ROLE_KEY;const encoded=objectPath.split('/').map(encodeURIComponent).join('/');await fetch(`${base}/storage/v1/object/findjob-private/${encoded}`,{method:'DELETE',headers:{Authorization:`Bearer ${key}`,apikey:key}});}catch(e){console.warn('Could not clean up an unlinked CV upload:',e.message);}}
async function extractResumeText(bytes,mime){try{if(mime==='application/pdf'){const {CanvasFactory}=await import('pdf-parse/worker');const {PDFParse}=await import('pdf-parse');const parser=new PDFParse({data:bytes,CanvasFactory});try{return String((await parser.getText({first:8})).text||'').slice(0,60000);}finally{await parser.destroy();}}if(mime==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'){const mod=await import('mammoth');const mammoth=mod.default||mod;return (await mammoth.extractRawText({buffer:bytes})).value.slice(0,60000);}}catch(e){console.warn('Resume text extraction unavailable:',e.message);}return '';}
function safeFilename(value){return String(value||'resume').normalize('NFKD').replace(/[^a-zA-Z0-9._-]+/g,'_').replace(/^\.+/,'').slice(0,100)||'resume';}
function sendDownload(res,buffer,filename,mime){res.writeHead(200,{'Content-Type':mime,'Content-Length':buffer.length,'Content-Disposition':`attachment; filename="${safeFilename(filename)}"`,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'});res.end(buffer);}
function applicationConfig(value){const v=value&&typeof value==='object'?value:{};const collectCv=v.collect_cv!==false;return {collect_cv:collectCv,cv_required:collectCv&&v.cv_required!==false,collect_cover_letter:v.collect_cover_letter!==false,collect_education:v.collect_education!==false,collect_experience:v.collect_experience!==false,additional_questions:(Array.isArray(v.additional_questions)?v.additional_questions:[]).map(x=>safeText(x,160)).filter(Boolean).slice(0,5)};}
function normaliseEmployerApply(value){const raw=String(value||'').trim();if(!raw)return '';if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(raw))return `mailto:${raw.toLowerCase()}`;return raw;}
function paystackSecret(){return process.env.PAYSTACK_SECRET_KEY||'';}
async function verifyPaystack(reference){
 const secret=paystackSecret();if(!secret)throw Error('Paystack is not configured. Add PAYSTACK_SECRET_KEY in Railway Variables.');
 const r=await fetch(`https://api.paystack.co/transaction/verify/${encodeURIComponent(reference)}`,{headers:{Authorization:`Bearer ${secret}`,Accept:'application/json'}});
 const data=await r.json().catch(()=>({}));if(!r.ok||!data.status||data.data?.status!=='success')throw Error('Paystack has not confirmed this payment yet.');return data.data;
}
async function settleEmployerPayment(reference,verified){
 const rows=await db('employer_payments',{query:`select=*&reference=eq.${encodeURIComponent(reference)}&limit=1`});const payment=rows[0];if(!payment)throw Error('Payment reference was not found.');
 if(verified.status!=='success'||Number(verified.amount)!==Number(payment.amount_kobo)||String(verified.currency||'').toUpperCase()!=='NGN')throw Error('The verified Paystack amount does not match this order.');
 if(verified.customer?.email&&verified.customer.email.toLowerCase()!==String((await db('employers',{query:`select=email&id=eq.${payment.employer_id}&limit=1`}))[0]?.email||'').toLowerCase())throw Error('Payment email does not match the employer account.');
 const meta=payment.metadata||{};
 await db('rpc/employer_settle_payment',{method:'POST',body:{p_reference:payment.reference,p_employer_id:payment.employer_id,p_amount_kobo:payment.amount_kobo,p_payment_kind:payment.payment_kind,p_quantity:payment.quantity||1,p_months:payment.months||0,p_metadata:{...meta,paystack_transaction_id:verified.id,channel:verified.channel,paid_at:verified.paid_at}},prefer:'return=representation'});
 return {ok:true,kind:payment.payment_kind,amount_kobo:payment.amount_kobo};
}
function query(url){return url.searchParams}
function validJob(input,existing){
 const title=safeText(input.title,180),company=safeText(input.company||'Employer not specified',130),location=safeText(input.location||'Nigeria',130);
 const description=sanitizeDescriptionHtml(input.description||'',26000);
 const enteredApplyRaw=String(input.apply_url||'').trim();let enteredApply=enteredApplyRaw;if(/^mailto:/i.test(enteredApplyRaw)){try{const u=new URL(enteredApplyRaw);enteredApply=`mailto:${decodeURIComponent(u.pathname)}`;}catch{enteredApply='';}}
 const extractedApply=extractApplicationDestination(description,title);
 const previousSource=String(input.source_url||existing?.source_url||'').trim();
 const apply_url=enteredApply&&enteredApply!==previousSource&&applicationUrlOk(enteredApply)?enteredApply:(extractedApply||'');
 const source_url=String(input.source_url||(urlOk(apply_url)?apply_url:(process.env.SITE_URL||'https://findjob.ng'))).trim();
 if(title.length<5||!urlOk(source_url)||!applicationUrlOk(apply_url))throw Error('Check the job title and original source URL. The application field can stay blank for jobs that need manual review.');
 const category=CATEGORIES.includes(input.category)?input.category:classify(title,description,location);
 const status=['pending','published','draft','rejected','expired','trashed'].includes(input.status)?input.status:'pending';
 const application_method=input.application_method==='internal'?'internal':'external';if(status==='published'&&!apply_url&&application_method!=='internal')throw Error('This job has no valid employer application email or URL. Keep it under Pending Review until one is confirmed.');
 if(status==='published'&&['myjobmag','jobicy'].includes(input.source_key)&&apply_url===source_url)throw Error('The Apply Now destination cannot be the source job-board listing');
 const verified=input.verified===true;
 return {title,company,location,description,excerpt:safeText(input.excerpt,220)||excerpt(description),apply_url,source_url,category,status,application_method,application_form_config:applicationConfig(input.application_form_config),verified,verification_note:safeText(input.verification_note,500),remote:input.remote===true,eligibility:['nigeria','global','restricted','unknown'].includes(input.eligibility)?input.eligibility:'unknown',expires_at:input.expires_at&&!isNaN(Date.parse(input.expires_at))?new Date(input.expires_at).toISOString():null,posted_at:input.posted_at&&!isNaN(Date.parse(input.posted_at))?new Date(input.posted_at).toISOString():null,published_at:status==='published'?(existing?.published_at||new Date().toISOString()):null,updated_at:new Date().toISOString()};
}
async function publicJobs(q){const p=new URLSearchParams({select:'id,slug,title,company,location,category,excerpt,description,apply_url,application_method,source_url,source_key,verified,posted_at,published_at,expires_at,remote,featured_until',status:'eq.published',limit:'100'});const category=q.get('category');if(category&&CATEGORIES.includes(category))p.set('category',`eq.${category}`);const sort=q.get('sort');p.set('order',sort==='oldest'?'published_at.asc':sort==='title'?'title.asc':sort==='location'?'location.asc':'published_at.desc');let rows=await db('jobs',{query:p.toString()});rows=rows.filter(j=>!j.expires_at||new Date(j.expires_at)>new Date());rows.sort((a,b)=>Number(new Date(b.featured_until||0)>Date.now())-Number(new Date(a.featured_until||0)>Date.now())||new Date(b.published_at||0)-new Date(a.published_at||0));const term=safeText(q.get('q'),120).toLowerCase();if(term){const words=term.split(/\s+/).filter(x=>!['jobs','job','in','at','for','the','me','find','a'].includes(x));rows=rows.filter(j=>words.every(w=>[j.title,j.company,j.location,j.category,j.excerpt].join(' ').toLowerCase().includes(w)));}const page=Math.max(1,Math.min(500,Number(q.get('page'))||1));return {jobs:rows.slice((page-1)*30,page*30).map(({description,...j})=>j),total:rows.length,page,pages:Math.max(1,Math.ceil(rows.length/30))};}
async function publicJob(slug){const rows=await db('jobs',{query:`select=*&slug=eq.${encodeURIComponent(slug)}&status=eq.published&limit=1`});const j=rows[0];return j&&(!j.expires_at||new Date(j.expires_at)>new Date())?j:null;}
async function publicConfig(){const [ads,settings,widgets]=await Promise.all([db('ads',{query:'select=slot,label,mode,image_url,click_url,adsense_slot,enabled,format,page_target,sort_order,placement_group&enabled=eq.true&order=sort_order.asc'}),db('site_settings',{query:'select=key,value'}),db('widgets',{query:'select=*&enabled=eq.true'})]);const safeSettings=Object.fromEntries(settings.filter(x=>!['header_code','footer_code'].includes(x.key)).map(x=>[x.key,x.value]));return {ads,widgets,settings:safeSettings};}
async function staffJobs(q){const status=q.get('status'),p=new URLSearchParams({select:'*',order:'created_at.desc',limit:'1000'});if(['pending','published','draft','rejected','expired','trashed'].includes(status))p.set('status',`eq.${status}`);return db('jobs',{query:p.toString()});}
async function audit(){const [jobs,staff,sources,ads,runs]=await Promise.all([dbAll('jobs','select=id,status'),db('staff',{query:'select=id,user_id,email,role,active&order=created_at.asc'}),db('sources',{query:'select=*'}),db('ads',{query:'select=*&order=slot.asc'}),db('sync_runs',{query:'select=*&order=created_at.desc&limit=15'})]);const widgets=await db('widgets',{query:'select=*&order=slot.asc'});return {widgets,stats:{total:jobs.length,pending:jobs.filter(x=>x.status==='pending').length,published:jobs.filter(x=>x.status==='published').length,draft:jobs.filter(x=>x.status==='draft').length,rejected:jobs.filter(x=>x.status==='rejected').length,expired:jobs.filter(x=>x.status==='expired').length,trashed:jobs.filter(x=>x.status==='trashed').length},staff,sources,ads,runs};}

function lagosMidnightUtc(date=new Date()){
 const local=new Date(date.getTime()+60*60*1000);
 return new Date(Date.UTC(local.getUTCFullYear(),local.getUTCMonth(),local.getUTCDate())-60*60*1000);
}
function metricsWindow(range){
 const today=lagosMidnightUtc();
 const days={today:0,yesterday:1,'3days':2,'1week':6,'2weeks':13,month:29,year:364,all:0};
 if(!(range in days))range='1week';
 const start=range==='yesterday'?new Date(today.getTime()-86400000):range==='all'?new Date('2000-01-01T00:00:00.000Z'):new Date(today.getTime()-days[range]*86400000);
 const end=range==='yesterday'?today:new Date();
 return {range,start:start.toISOString(),end:end.toISOString(),todayStart:today.toISOString()};
}
